#!/usr/bin/env bash\n# test_uptime_emoji.sh - Tests for uptime_emoji.sh\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/../src\" && pwd)\"\nSCRIPT=\"$SCRIPT_DIR/uptime_emoji.sh\"\n\n# Helper to run a single test case\nrun_test() {\n  local uptime_value=$1\n  local expected_emoji=$2\n  local tmpfile\n  tmpfile=$(mktemp)\n  echo \"$uptime_value 0\" > \"$tmpfile\"\n\n  output=$($SCRIPT \"$tmpfile\")\n  rm \"$tmpfile\"\n\n  if [[ \"$output\" != *\"$expected_emoji\"* ]]; then\n    echo \"FAIL: Expected emoji $expected_emoji in output '$output'\"\n    exit 1\n  fi\n  echo \"PASS: $uptime_value seconds -> $expected_emoji\"\n}\n\n# Test less than a day (12 hours)\nrun_test \"43200\" \"🌱\"\n\n# Test between 1 and 7 days (3 days)\nrun_test \"259200\" \"🌿\"\n\n# Test more than 7 days (10 days)\nrun_test \"864000\" \"🌳\"\n\necho \"All tests passed.\"
